	return ccb
}

func (ccb *ccBalancerWrapper) watcher() {
	for {
		select {
		case t := <-ccb.stateChangeQueue.get():
			ccb.stateChangeQueue.load()
			select {
			case <-ccb.done:
				ccb.balancer.Close()
				return
			default:
			}
			if ub, ok := ccb.balancer.(balancer.V2Balancer); ok {
				ub.UpdateSubConnState(t.sc, balancer.SubConnState{ConnectivityState: t.state})
			} else {
				ccb.balancer.HandleSubConnStateChange(t.sc, t.state)
			}
		case err := <-ccb.resolverErrorCh:
			if ub, ok := ccb.balancer.(balancer.V2Balancer); ok {
				ub.ResolverError(err)
			} else {
				ccb.balancer.HandleResolvedAddrs(nil, err)
			}
		case s := <-ccb.ccUpdateCh:
			select {
			case <-ccb.done:
				ccb.balancer.Close()
				return
			default:
			}
			if ub, ok := ccb.balancer.(balancer.V2Balancer); ok {
				if err := ub.UpdateClientConnState(*s); err == balancer.ErrBadResolverState {
					ccb.ResolveNow(resolver.ResolveNowOption{})
				}
			} else {
				ccb.balancer.HandleResolvedAddrs(s.ResolverState.Addresses, nil)
			}
		case <-ccb.done:
			ccb.balancer.Close()
			ccb.mu.Lock()
			scs := ccb.subConns
			ccb.subConns = nil
			ccb.mu.Unlock()
			for acbw := range scs {
				ccb.cc.removeAddrConn(acbw.getAddrConn(), errConnDrain)
			}
			ccb.UpdateBalancerState(connectivity.Connecting, nil)
			return
		}
		ccb.cc.firstResolveEvent.Fire()
	}
}

func (ccb *ccBalancerWrapper) reportResolverError(err error) {
	select {
	case ccb.resolverErrorCh <- err:
	case <-ccb.done:
	}
}

func (ccr *ccResolverWrapper) ReportError(err error) {
	if ccr.isDone() {
